// ALICE n8n Context Bridge v1 — bounded, explicit, non-sensitive notes only.
// Requires Header Auth on the Webhook node; no secret values belong here.
const incoming = $input.first().json.body;
const body = (incoming && typeof incoming === 'object' && !Array.isArray(incoming)) ? incoming : {};
const operation = String(body.operation || '').toLowerCase();
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.notes)) store.notes = [];
const fail = (code, message) => [{ json: { ok:false, code, message } }];
if (operation === 'health') {
  return [{json:{ok:true,service:'alice-context-bridge',version:1,storage:'n8n workflow static data (pilot)', timestamp:new Date().toISOString()}}];
}
if (operation === 'catalog') {
  return [{json:{ok:true,services:[
    {name:'GitHub',role:'repository + CI',credential_location:'n8n Credentials or connected ChatGPT app',automatic_sync:false},
    {name:'Vercel',role:'cloud API/deployments',credential_location:'Vercel secure environment / n8n Credentials',automatic_sync:false},
    {name:'OpenAI Platform',role:'model API separate from ChatGPT chats',credential_location:'n8n Credentials',automatic_sync:false},
    {name:'Android',role:'opt-in device bridge',credential_location:'device local',automatic_sync:false}
  ],allowed_operations:['health','catalog','publish','list'],writes_to_external_apis:false}}];
}
if (operation === 'publish') {
  const note=String(body.note ?? '').trim();
  const source=String(body.source ?? '').trim();
  const channel=String(body.channel ?? 'general').trim();
  const eventId=String(body.event_id ?? '').trim();
  if (body.user_approved !== true) return fail('CONSENT_REQUIRED','Explicit user_approved=true required per note');
  if (!['chatgpt','android','n8n','cloud'].includes(source)) return fail('INVALID_SOURCE','Unsupported source');
  if (!/^[a-zA-Z0-9_-]{1,40}$/.test(channel)) return fail('INVALID_CHANNEL','Channel must be 1-40 safe characters');
  if (!/^[a-zA-Z0-9_-]{8,80}$/.test(eventId)) return fail('INVALID_ID','Supply a unique, non-sensitive event_id');
  if (!note || note.length > 1200) return fail('INVALID_NOTE','Note must contain 1-1200 characters');
  if (/(sk-(proj-)?[a-zA-Z0-9_-]{12,}|Bearer\s+[a-zA-Z0-9._-]{16,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)/i.test(note))
    return fail('SECRET_REJECTED','Possible credential detected; remove it');
  const prior=store.notes.find(n=>n.event_id===eventId);
  if (prior) return [{json:{ok:true,duplicate:true,event_id:eventId}}];
  store.notes.push({event_id:eventId,source,channel,note,created_at:new Date().toISOString()});
  if (store.notes.length > 30) store.notes=store.notes.slice(-30);
  return [{json:{ok:true,stored:true,event_id:eventId,items:store.notes.length}}];
}
if (operation === 'list') {
  const channel=String(body.channel ?? '').trim();
  if (channel && !/^[a-zA-Z0-9_-]{1,40}$/.test(channel)) return fail('INVALID_CHANNEL','Invalid channel');
  const count=Math.min(Math.max(Number(body.limit || 10),1),30);
  const list=(channel ? store.notes.filter(n=>n.channel===channel) : store.notes);
  return [{json:{ok:true,notes:list.slice(-count).reverse(),total_visible:list.length}}];
}
return fail('UNKNOWN_OPERATION','Allowed: health, catalog, publish, list');
